-- MIGRACIÓN MANUAL. No ejecutada en Supabase.
-- Requiere renderer con bloques arrendador-v1-moral-1.
-- Fuente: docs/plantillas/contrato-habitacional-v2-final.html (UTF-8).
BEGIN;
SET LOCAL lock_timeout = '10s';
-- Serializa el chequeo y la inserción, incluso frente a escrituras ajenas a este script.
LOCK TABLE public.plantillas, public.versiones_plantilla IN SHARE ROW EXCLUSIVE MODE;
DO $migration$
DECLARE
  v_parent uuid;
  v_original public.versiones_plantilla%ROWTYPE;
  v_existing public.versiones_plantilla%ROWTYPE;
  v_html constant text := $v2html$<br><br><h1 style="text-align:center;">CONTRATO DE ARRENDAMIENTO</h1><br><br><p><br>{{arrendador.bloques.comparecencia}}, y por la otra parte<br><strong>{{arrendatario.nombre_completo}}</strong> a quien se le denominará<br>como EL ARRENDATARIO y <strong>{{fiador.nombre_completo}}</strong> como<br>FIADOR quienes manifestaron su voluntad de celebrar el presente contrato<br>por así convenir a sus intereses, basándose en los antecedentes que son<br>del orden siguiente:<br></p><br><br><h2 style="text-align:center;">ANTECEDENTES</h2><br><br>{{arrendador.bloques.antecedentes_identidad}}<p><br>c) Ser propietario en legítima propiedad, posesión y pleno dominio del<br>Inmueble ubicado en <strong>{{inmueble.direccion_completa}}</strong><br>(en adelante EL INMUEBLE); y que es su deseo dar en arrendamiento<br><strong>{{unidad.nombre}}</strong> al ARRENDATARIO en los términos que<br>se establezcan en este Contrato.<br></p><br><br><p><br>d) Que EL INMUEBLE cuenta con las condiciones de higiene y salubridad<br>exigidas por la Ley para ser usado como departamento.<br></p><br><br><p><br>Que incluye el siguiente inventario de bienes, muebles y accesorios:<br></p><br><br><p><br>____________________________________________________________________________<br><br>____________________________________________________________________________<br><br>____________________________________________________________________________<br><br>____________________________________________________________________________<br><br>____________________________________________________________________________<br></p><br><br><p><br><strong>II.- EL ARRENDATARIO, {{arrendatario.nombre_completo}}</strong>,<br>bajo protesta de decir verdad manifiesta:<br></p><br><br><p><br>a) Ser mexicano, mayor de edad, tener capacidad para celebrar este<br>contrato y tener un modo honesto de vivir.<br></p><br><br><p><br>b) Que ha constatado personalmente las condiciones físicas de<br>EL INMUEBLE y sus instalaciones, y está de acuerdo en la seguridad<br>e higiene de las instalaciones.<br></p><br><br><p><br>c) Que EL INMUEBLE que por este contrato está arrendando se dedicará<br>exclusivamente para uso habitacional, y que bajo ninguna circunstancia<br>el mismo será utilizado o relacionado para cometer los ilícitos a que<br>se refiere la LEY DE EXTINCIÓN DE DOMINIO para el ESTADO DE NUEVO LEÓN<br>o cualesquier otro delito comprendido en el Código Penal del Estado o<br>cualquier otra legislación que tipifique otros delitos y que el dinero<br>que utilizará para el pago de las pensiones rentarías es de procedencia<br>lícita y comprobable.<br></p><br><br><p><strong>III.- Finalmente ambas partes manifiestan:</strong></p><br><br><p><br>a) Su expresa conformidad con los mencionados ANTECEDENTES y por<br>consecuencia deciden celebrar el presente CONTRATO DE ARRENDAMIENTO DE<br>BIEN INMUEBLE sujetándolo a los términos y condiciones que se establecen<br>por medio del mismo.<br></p><br><br><p><br>b) Que se reconocen e identifican mutuamente, manifestando tener<br>capacidad suficiente para la celebración del presente Contrato, estando<br>facultados para obligarse en los términos y condiciones que en el<br>presente contrato se precisan.<br></p><br><br><p><br>c) Que conocen el contenido y alcance legal de la LEY FEDERAL DE<br>EXTINCIÓN DE DOMINIO, REGLAMENTARIA DEL ARTÍCULO 22 VEINTIDÓS DE LA<br>CONSTITUCIÓN POLÍTICA DE LOS ESTADOS UNIDOS MEXICANOS y de la LEY DE<br>EXTINCIÓN DE DOMINIO PARA EL ESTADO DE NUEVO LEÓN por lo cual manifiestan<br>bajo protesta de decir verdad que los recursos económicos utilizados<br>para la celebración del presente acto son de procedencia lícita y<br>comprobable, que el destino de los mismos serán para la realización de<br>actividades lícitas y que realizan el presente acto de buena fe.<br></p><br><br><p><br>d) Manifiestan los comparecientes que de conformidad con la Ley para la<br>Prevención e Identificación de Operaciones con Recursos de Procedencia<br>Ilícita, lo siguiente: a).- Que el acto consignado en este contrato<br>constituye una actividad vulnerable de acuerdo con lo que establece la<br>Ley de la materia. b).- Que en el presente contrato actúan en su nombre<br>y por cuenta propia, manifestando bajo protesta de decir verdad que no<br>existe un tercero beneficiario controlador que se beneficie del presente<br>acto. c).- Por último que en esta operación se han sujetado a las<br>restricciones sobre el cumplimiento a obligaciones y, en general,<br>liquidar o pagar, así como aceptar la liquidación o el pago, mediante<br>el uso de monedas y billetes, en moneda nacional o divisas y Metales<br>Preciosos.<br></p><br><br><p><br>e) Que desean celebrar el presente Contrato de Arrendamiento de acuerdo<br>al contenido de las siguientes:<br></p><br><br><h2 style="text-align:center;">CLÁUSULAS</h2><br><br><p><br><strong>PRIMERA: OBJETO.-</strong><br>EL ARRENDADOR otorga en arrendamiento al ARRENDATARIO, EL INMUEBLE<br>descrito en el Antecedente I (PRIMERO) de este Contrato.<br></p><br><br><p><br><strong>SEGUNDA: POSESIÓN.-</strong><br>EL ARRENDADOR manifiesta que en ESTA FECHA se entregará en arrendamiento<br>EL INMUEBLE objeto del presente contrato, en las condiciones ya descritas<br>en el capítulo de ANTECEDENTES arriba trascrito y previa inspección que<br>EL ARRENDATARIO realice a fin de verificar lo anterior, haciéndole<br>mención de que tendrá que cubrir puntualmente el pago de luz. Ya está<br>incluido en el arrendamiento el servicio de internet y agua para uso<br>personal. El uso de la lavandería sería un costo adicional de {{contrato.costo_lavanderia}}<br>mensuales por persona, en caso de requerir dicho servicio.<br></p><br><br><p><br><strong>TERCERA: MONTO DE RENTA MENSUAL Y TÉRMINOS DE PAGO.-</strong><br>EL ARRENDATARIO en este acto se obliga a pagar por concepto de renta la<br>cantidad de <strong>{{contrato.renta}} ({{contrato.renta_letra}})</strong><br>netos mensuales.<br></p><br><br><p><br>La renta será pagada los días <strong>{{contrato.dia_pago}}</strong><br>de cada mes correspondiente al pago, a partir del<br><strong>{{contrato.fecha_inicio_letra}}</strong>, teniendo como margen<br>para pagar los siguientes 5 días. De no ser así, al sexto día se cobrará<br>la cantidad de $100.00 (cien pesos 00/100 m.n.) por día retrasado en<br>el pago.<br></p><br><br><p><br><strong>CUARTA: VIGENCIA.-</strong><br>EL ARRENDADOR y EL ARRENDATARIO acuerdan y así lo establecen en la<br>presente cláusula, que la duración del presente Contrato será contada a partir del<br><strong>{{contrato.fecha_inicio_letra}}</strong>, para concluir el día<br><strong>{{contrato.fecha_fin_letra}}</strong>. En caso de que las partes<br>decidan renovar el contrato el aumento de la renta será tendrá un aumento<br>anual con base al índice de inflación del Banco de México.<br></p><br><br><p><br><strong>QUINTA: DEL DEPÓSITO.-</strong><br>Para garantizar todas y cada una de las obligaciones que se derivan del<br>presente contrato, EL ARRENDATARIO hará entrega EL ARRENDADOR, de la<br>cantidad de<br><strong>{{contrato.deposito}} ({{contrato.deposito_letra}})</strong>.<br></p><br><br><p><br>Éste depósito será devuelto por “EL ARRENDADOR” a “EL ARRENDATARIO”<br>a más tardar a los treinta (30) días naturales posteriores al término<br>de este Contrato o posteriores a sus renovaciones o en su caso<br>posteriores a la entrega física del inmueble arrendado, EN LA MISMA<br>CANTIDAD Y MONEDA, siempre y cuando EL INMUEBLE arrendado se entregue<br>en el mismo buen estado en el que se recibió, salvo por el deterioro<br>normal por su uso, y que no existan adeudos pendientes de pago por<br>pensiones rentísticas de luz, y/o cualquier otro cargo no cubierto de<br>esta naturaleza.<br></p><br><br><p><br><strong>SEXTA: DEL FIADOR.-</strong><br>Para garantizar el cumplimiento de todas y cada una de las obligaciones<br>que se derivan del presente Contrato, incluyendo las penas convencionales<br><strong>{{fiador.nombre_completo}}</strong> se constituye como FIADOR<br>del ARRENDATARIO. Tal responsabilidad será efectiva no solamente durante<br>la vigencia de este contrato, sino por todo el tiempo en que<br>EL ARRENDATARIO ocupe el inmueble o adeude a EL ARRENDADOR cantidad<br>alguna por cualquier concepto derivado del contrato o de la ley.<br></p><br><br><p><br>En el entendido que el FIADOR garantiza sobre el monto total de la<br>RENTA, así como de los pagos relativos a los servicios con los pudiere<br>contratar a su cuenta y cargo (teléfono, televisión de paga y conexión<br>a Internet, entre otros) EL ARRENDATARIO en materia del presente<br>Contrato.<br></p><br><br><p><br><strong>SÉPTIMA: DE LA TERMINACIÓN ANTICIPADA.-</strong><br>El presente contrato de arrendamiento se podrá dar por terminado<br>anticipadamente en cualquier tiempo, si el ARRENDATARIO desea desocupar<br>EL INMUEBLE arrendado antes del vencimiento del contrato, podrá hacerlo,<br>con el previo aviso por escrito de por lo menos 60 (SESENTA) días de<br>anticipación a EL ARRENDADOR, en cuyo caso EL ARRENDATARIO se obliga a<br>pagarle a EL ARRENDADOR como pena convencional la suma de 1 (UN) mes de<br>renta si lo llegase a desocupar antes del término de fecha de<br>arrendamiento. No contando como pago de un mes la cantidad otorgada<br>previamente como depósito en garantía, ni contando tampoco el depósito<br>pagado como pago del último mes de renta.<br></p><br><br><p><br>Al efecto, EL ARRENDATARIO renuncia expresamente a los privilegios y<br>prórrogas que establecen los artículos 2379, 2380 y 2381 del Código<br>Civil del Estado.<br></p><br><br><p><br><strong>OCTAVA: DE LAS OBLIGACIONES DEL ARRENDATARIO.-</strong><br>EL ARRENDATARIO se compromete durante la vigencia del presente Contrato a:<br></p><br><br><p><br>a) Pagar la RENTA en la forma y plazo convenidos los primeros cinco<br>(05) días naturales -inclusive- de cada período mensual.<br><br>b) Responder por cualquier daño que sufra EL INMUEBLE por su culpa o<br>negligencia, ya sea por actos u omisiones de él, o de las personas a<br>las que haya permitido el acceso al mismo.<br><br>c) No subarrendar, ni traspasar, ni conceder derecho alguno sobre<br>EL INMUEBLE sin el previo consentimiento por escrito de EL ARRENDADOR.<br><br>d) A no manejar sustancias tóxicas u explosivas (excluyendo el uso<br>doméstico del gas), dentro del Inmueble, en la inteligencia de que será<br>responsable de cualquier daño y perjuicio que provoque por negligencia<br>en EL INMUEBLE, como fuga de agua, incendio, explosión, etc.<br><br>e) A no efectuar modificaciones en “EL INMUEBLE” sin el consentimiento<br>por escrito de EL ARRENDADOR.<br><br>f) A sacar en paz y a salvo al ARRENDADOR de todo litigio, proceso o<br>reclamación derivada del presente contrato que le sean imputables a él,<br>sus cohabitantes y/o visitantes.<br><br>g) Servirse de la cosa para el uso convenido en este contrato.<br><br>h) Dar un uso legal y pacífico a EL INMUEBLE y procurar la sana<br>convivencia y el decoro dentro de EL INMUEBLE, evitando así el ruido<br>excesivo. El incumplimiento de esta disposición será acreedor a<br>rescisión de contrato.<br><br>i) Avisar por escrito al ARRENDADOR en breve tiempo, máximo 1 un día<br>hábil desde que haya tenido conocimiento, de toda usurpación o novedad<br>dañosa que otro haya hecho o abiertamente se prepare contra la cosa<br>arrendada.<br><br>j) A devolver el inmueble en las condiciones y fecha establecidas en<br>el presente contrato.<br><br>k) A dar mantenimiento a los climas cada 6 meses.<br></p><br><br><p><br><strong>NOVENA: DE LAS OBLIGACIONES DEL ARRENDADOR.-</strong><br>EL ARRENDADOR se compromete durante la vigencia del presente Contrato a:<br></p><br><br><p><br>a) Responder por todas las reparaciones a la estructura del INMUEBLE,<br>ya sean por fallas en el diseño, vicios ocultos, terremotos, etc.,<br>comprometiéndose a efectuarlas a la mayor brevedad posible. (30 DIAS)<br>En caso de que el ARRENDATARIO tuviese que hacer dichas reparaciones<br>por premura de tiempo, previa aprobación del presupuesto correspondiente<br>por parte del ARRENDADOR, podrá llevar a cabo el trabajo. Los gastos de<br>las reparaciones, en caso de fuerza mayor, se compromete el ARRENDADOR<br>a reembolsar a la brevedad posible con un máximo de diez (10) días<br>naturales, a partir de recibir el presupuesto respectivo.<br><br>b) Pagar el impuesto predial del inmueble respecto al INMUEBLE<br>arrendado.<br><br>c) A garantizar el uso pacífico de la cosa por todo el tiempo del<br>contrato sin intervenir en el uso del inmueble sin consentimiento<br>previo de las partes.<br><br>d) EL ARRENDADOR no se hace responsable por siniestros, accidentes,<br>robos, incidentes, incendios, derrumbes, naufragios, etc. dentro o<br>fuera del inmueble.<br><br>e) EL ARRENDADOR se compromete a entregar EL INMUEBLE al ARRENDATARIO,<br>a más tardar el día de firma de este contrato.<br></p><br><br><p><br><strong>DÉCIMA: DEL DOMICILIO.-</strong><br>Para todo aviso relacionado con el presente Contrato, las partes<br>firmantes señalan como sus domicilios para todo lo relacionado en el<br>presente Contrato los siguientes:<br></p><br><br><p><br><strong>EL ARRENDADOR:</strong><br><br>{{contrato.domicilio_arrendador}}<br></p><br><br><p><br><strong>EL ARRENDATARIO:</strong><br><br>{{contrato.domicilio_arrendatario}}<br></p><br><br><p><br><strong>EL FIADOR:</strong><br><br>{{contrato.domicilio_fiador}}<br></p><br><br><p><br><strong>DÉCIMA PRIMERA: JURISDICCIÓN.-</strong><br>Para todo lo relacionado con la correcta interpretación, cumplimiento<br>y ejecución del presente Contrato, las partes convienen expresamente en<br>sujetarse a las leyes aplicables y a los tribunales con jurisdicción en<br>el lugar de la ubicación del inmueble materia del presente arrendamiento,<br>renunciando a cualquier fuero que por razón de sus domicilios presentes<br>o futuros pudieran corresponderles.<br></p><br><br><p style="text-align:center;"><br><strong><br>ESTANDO CONFORMES CON SU CONTENIDO, LAS PARTES OTORGAN Y FIRMAN ESTE<br>CONTRATO EN {{contrato.lugar_firma}}, EL DÍA<br>{{contrato.fecha_firma_letra}}<br></strong><br></p><br><br><table style="width:100%; text-align:center; margin-top:60px;"><br>    <tbody><br>        <tr><br>            <td style="width:50%; vertical-align:top;"><br>                <strong>EL ARRENDADOR</strong><br><br><br><br>                ______________________________<br><br>                {{arrendador.bloques.firma}}<br>            </td><br><br>            <td style="width:50%; vertical-align:top;"><br>                <strong>EL ARRENDATARIO</strong><br><br><br><br>                ______________________________<br><br>                {{arrendatario.nombre_completo}}<br>            </td><br>        </tr><br><br>        <tr><br>            <td colspan="2" style="padding-top:60px;"><br>                <strong>EL FIADOR</strong><br><br><br><br>                ______________________________<br><br>                {{fiador.nombre_completo}}<br>            </td><br>        </tr><br>    </tbody><br></table><br><br>$v2html$;
BEGIN
  SELECT * INTO v_original FROM public.versiones_plantilla
  WHERE id = '8f30e17c-6c5e-4a42-9b66-d0d8348d9520'::uuid;
  IF NOT FOUND THEN RAISE EXCEPTION 'No existe la V1 esperada'; END IF;
  IF v_original.numero_version IS DISTINCT FROM 1
     OR md5(v_original.contenido) IS DISTINCT FROM 'd704f77fe239de4baa7f3ba952717a4e'
     OR length(v_original.contenido) IS DISTINCT FROM 15582
     OR octet_length(v_original.contenido) IS DISTINCT FROM 15747 THEN
    RAISE EXCEPTION 'La versión origen no coincide con la V1 verificada (número o contenido)';
  END IF;
  SELECT id INTO v_parent FROM public.plantillas
  WHERE id = v_original.plantilla_id AND nombre = 'Contrato de arrendamiento habitacional';
  IF NOT FOUND THEN RAISE EXCEPTION 'V1 no pertenece a la plantilla esperada'; END IF;
  IF (SELECT count(*) FROM public.versiones_plantilla WHERE plantilla_id = v_parent AND numero_version = 2) > 1 THEN
    RAISE EXCEPTION 'Existen varias V2 para esta plantilla';
  END IF;
  SELECT * INTO v_existing FROM public.versiones_plantilla
  WHERE plantilla_id = v_parent AND numero_version = 2;
  IF FOUND THEN
    IF v_existing.contenido IS DISTINCT FROM v_html OR v_existing.estado IS DISTINCT FROM 'BORRADOR' THEN
      RAISE EXCEPTION 'Ya existe V2 con contenido o estado diferente; no se sobrescribe';
    END IF;
    RAISE NOTICE 'V2 BORRADOR idéntica ya existe; no se insertó otra versión';
    RETURN;
  END IF;
  INSERT INTO public.versiones_plantilla (id, plantilla_id, numero_version, estado, contenido)
  VALUES (gen_random_uuid(), v_parent, 2, 'BORRADOR', v_html);
END
$migration$;
COMMIT;
